const getRackAssetsForShrinkCheck = `-- name: GetRackAssetsForShrinkCheck :many
SELECT name, rack_position_u, rack_units
FROM assets
WHERE rack_id = $1
  AND rack_position_u IS NOT NULL
`

type RackPlacedAsset struct {
	Name          string `json:"name"`
	RackPositionU *int32 `json:"rack_position_u"`
	RackUnits     *int32 `json:"rack_units"`
}

func (q *Queries) GetRackAssetsForShrinkCheck(ctx context.Context, rackID uuid.UUID) ([]RackPlacedAsset, error) {
	rows, err := q.db.Query(ctx, getRackAssetsForShrinkCheck, rackID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RackPlacedAsset
	for rows.Next() {
		var a RackPlacedAsset
		if err := rows.Scan(&a.Name, &a.RackPositionU, &a.RackUnits); err != nil {
			return nil, err
		}
		items = append(items, a)
	}
	return items, rows.Err()
}
